/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountLocaleSwitch, type LocaleSwitchOptions } from "../../components/locale-switch/LocaleSwitchEngine.js";
import type { MotionController } from "../../components/locale-switch/motion-runtime";

export function LocaleSwitch(props: { options?: LocaleSwitchOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountLocaleSwitch(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="locale-switch" />;
}

